// index = 0...503 
//
var start = new Date();
start.setHours(0,0,0,0);
start.setDate(start.getDate()-10);

var index = prevMetadata.index ? Number(prevMetadata.index) : 0;
var msgsPerShift = 8;

var shiftIndex = Math.floor(index / msgsPerShift);
var day = Math.floor(shiftIndex / 3);
var shift = shiftIndex % 3;

var shiftHour = [0,8,16][shift];

var shiftStart = new Date(start);
shiftStart.setDate(start.getDate()+day);
shiftStart.setHours(shiftHour,0,0,0);

var step = index % msgsPerShift;

// 8 events spread across the 8-hour shift
var slotStartMin = step * 60;

// Random minute (0-59) and second (0-59)
var randomMin = Math.floor(Math.random() * 60);
var randomSec = Math.floor(Math.random() * 60);

// Historical timestamp
var ts = shiftStart.getTime()
        + (slotStartMin + randomMin) * 60000
        + randomSec * 1000;

var state = "running";

// if(step === 0 || step === 7){
//     state = "idle";
// }

var good = state === "running"
    ? Math.round(180 + Math.random()*90)
    : 0;

var reject = state === "running"
    ? Math.round(Math.random()*8)
    : 0;

return {
    msg:{
        machine_status: state,
        good_count: good,
        reject_count: reject
    },
    metadata:{
        // shiftStart: shiftStart.getTime(),
        ts:String(ts),
        // tsString: new Date(ts),
        index: String(index + 1)
    },
    msgType:"POST_TELEMETRY_REQUEST"
};

